package com.medicore.order.entity; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="orders") public class Order {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long userId; @ElementCollection private List<OrderItem> items=new ArrayList<>(); @Column(nullable=false) private String status="CONFIRMED"; protected Order(){} public Order(Long userId,List<OrderItem> items){this.userId=userId;this.items=items;} public Long getId(){return id;} public Long getUserId(){return userId;} public List<OrderItem> getItems(){return items;} public String getStatus(){return status;}}
